    it('returns not-found when resolveEntry yields nothing', async () => {
      const resolveEntry = vi.fn().mockResolvedValue(undefined);

      const request = {
        jsonrpc: '2.0' as const,
        id: 1,
        method: 'tools/call',
        params: { name: GET_TOOL_NAME, arguments: { id: 'nope' } },
