      id: 'button',
      name: 'Button',
      subcomponents: {
        Icon: { name: 'Icon', path: 'src/Icon.tsx', reactComponentMeta: { props: {} } },
      },
    };

    const result = adaptCoreComponent(core);
    expect(result.subcomponents).toEqual(core.subcomponents);
  });
});

import type { ComponentManifest, CoreDocgenComponent, CoreMdxDoc, Doc, Story } from '../types.ts';

/**
 * Adapts Storybook's `experimentalDocgenServer` open-service payloads (the "core
 * format") into `@storybook/mcp`'s internal {@link ComponentManifest}/{@link Doc}
 * shapes. This is the single place that bridges the two formats, used by both the
 * ref-resolution path (built/static/remote manifests) and the addon's in-process
 * `resolveEntry` hook (dev).
 *
 * Only `argTypes` is dropped: prop types still come from `reactComponentMeta` and
 * the `react*` docgen-engine fields, which are passed through unchanged.
 */

const ARG_TYPES_KEY = 'argTypes';

/** Converts the story-docs `stories` record (or an already-resolved array) into `Story[]`. */
export function adaptCoreStories(stories: CoreDocgenComponent['stories']): Story[] | undefined {
  if (!stories) {
    return undefined;
  }
  if (Array.isArray(stories)) {
    return stories;
  }
  return Object.values(stories);
}

/** Adapts one MDX service payload into a {@link Doc}. */
export function adaptCoreDoc(doc: CoreMdxDoc): Doc {
  return { ...doc };
}

/** Adapts a core-format component (docgen + story-docs + attached MDX) into a {@link ComponentManifest}. */
export function adaptCoreComponent(core: CoreDocgenComponent): ComponentManifest {
  const { stories, docs, [ARG_TYPES_KEY]: _argTypes, ...rest } = core;
  const component = { ...rest } as ComponentManifest;

  const adaptedStories = adaptCoreStories(stories);
  if (adaptedStories) {
    component.stories = adaptedStories;
  }

  if (docs) {
    component.docs = Object.fromEntries(
      Object.entries(docs).map(([id, doc]) => [id, adaptCoreDoc(doc)])
    );
  }

  return component;
}

/**
 * Copied from https://github.com/tamino-martinius/node-ts-dedent/blob/18c4736c79806d7fe78bdaaaf5ae307b79f9574a/src/index.ts
 *
 * Rationale for vendoring instead of using the ts-dedent package:
 * 1. The package has a broken ESM distribution - the IDE auto-imports as
 *    `import dedent from 'ts-dedent'` but that breaks at runtime, requiring
 *    manual changes to named imports. See:
 *    - https://github.com/tamino-martinius/node-ts-dedent/issues/42
 *    - https://github.com/tamino-martinius/node-ts-dedent/pull/41
 * 2. Keeps bundle size smaller for such a simple utility (avoid "is-even" syndrome)
 */

export function dedent(templ: TemplateStringsArray | string, ...values: unknown[]): string {
  let strings = Array.from(typeof templ === 'string' ? [templ] : templ);

  // 1. Remove trailing whitespace.
  strings[strings.length - 1] = strings.at(-1)!.replace(/\r?\n([\t ]*)$/, '');

  // 2. Find all line breaks to determine the highest common indentation level.
  const indentLengths = strings.reduce((arr, str) => {
    const matches = str.match(/\n([\t ]+|(?!\s).)/g);
    if (matches) {
      return arr.concat(matches.map((match) => match.match(/[\t ]/g)?.length ?? 0));
    }
    return arr;
  }, [] as number[]);

  // 3. Remove the common indentation from all strings.
  if (indentLengths.length) {
    const pattern = new RegExp(`\n[\t ]{${Math.min(...indentLengths)}}`, 'g');

    strings = strings.map((str) => str.replace(pattern, '\n'));
  }

  // 4. Remove leading whitespace.
  strings[0] = strings[0]!.replace(/^\r?\n/, '');

  // 5. Perform interpolation.
  let string = strings[0];

  values.forEach((value, i) => {
    // 5.1 Read current indentation level
    const endentations = string.match(/(?:^|\n)( *)$/);
    const endentation = endentations ? endentations[1] : '';
    let indentedValue = value;
    // 5.2 Add indentation to values with multiline strings
    if (typeof value === 'string' && value.includes('\n')) {
      indentedValue = String(value)
        .split('\n')
        .map((str, i) => {
          return i === 0 ? str : `${endentation}${str}`;
        })
        .join('\n');
    }

    string += `${String(indentedValue)}${strings[i + 1]}`;
  });

  return string;
}

import { describe, it, expect } from 'vitest';
import { errorToMCPContent, ManifestGetError } from './get-manifest.ts';

describe('errorToMCPContent', () => {
  it('should convert ManifestGetError to MCP error content', () => {
    const error = new ManifestGetError('Failed to get', 'https://example.com');

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Error getting manifest: Failed to get',
        },
      ],
      isError: true,
    });
  });

  it('should convert generic Error to MCP error content', () => {
    const error = new Error('Something went wrong');

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Unexpected error: Something went wrong',
        },
      ],
      isError: true,
    });
  });

  it('should handle ManifestGetError with cause', () => {
    const cause = new Error('Network error');
    const error = new ManifestGetError('Failed to get manifest', 'https://example.com', cause);

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Error getting manifest: Failed to get manifest\nCaused by: Network error',
        },
      ],
      isError: true,
    });
  });

