      path: './manifests/button.json',
      pointer: ['components', 'button'],
    });
  });

  it('decodes JSON-pointer escape sequences', () => {
    expect(parseManifestRef('../x.json#/a~1b/c~0d')).toEqual({
      path: './x.json',
      pointer: ['a/b', 'c~d'],
    });
  });
});

